parameters.jsCode:
// Pull the JSON answer out of the response, one item per candidate, with a normalised URL for de-duplication
const j = $input.first().json;
const text = j.output?.flatMap(o => o.content || []).find(c => c.type === 'output_text')?.text ?? j.text ?? '';
let list = []; try { list = (typeof text === 'object' ? text : JSON.parse(text)).candidates || []; } catch (e) {}
const max = Number($('Task + Search Skill').first().json.max_results) || 10;
return list.filter(c => /^https?:\/\//.test(c.url || '')).slice(0, max)
  .map(c => ({ json: { ...c, url_norm: c.url.replace(/#.*$/, '').replace(/[?&]utm_[^&]+/g, '').replace(/\/$/, '').toLowerCase() } }));
